/**
 * Sakina service worker.
 *
 * Hand-written rather than generated by Workbox/Serwist for one reason: this
 * app caches large audio files that browsers request with HTTP Range headers,
 * and generic runtime-caching recipes answer those with a 200 containing the
 * whole body. Safari in particular then refuses to seek, or refuses to play at
 * all. Handling ranges correctly is the whole job here, so the logic is
 * explicit and readable.
 *
 * Cache layout:
 *   sakina-shell-v1   app shell + icons, precached on install
 *   sakina-pages-v1   visited HTML, stale-while-revalidate
 *   sakina-assets-v1  hashed JS/CSS/fonts/images, cache-first
 *   quran-audio-v1    downloaded surahs, written by the app (not by this file)
 */

const VERSION = "v1";
const SHELL = `sakina-shell-${VERSION}`;
const PAGES = `sakina-pages-${VERSION}`;
const ASSETS = `sakina-assets-${VERSION}`;

/** Written by the download feature; this worker only reads from it. */
const AUDIO = "quran-audio-v1";

const OWNED = new Set([SHELL, PAGES, ASSETS, AUDIO]);

/**
 * Kept deliberately small. Route HTML is cached on first visit instead, so a
 * failed precache of one page can never block the install of the whole worker.
 */
const SHELL_URLS = [
  "/",
  "/manifest.webmanifest",
  "/icon.svg",
  "/icon-192.png",
  "/icon-512.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL);
      // Individually, so one 404 does not abort the entire install.
      await Promise.allSettled(SHELL_URLS.map((url) => cache.add(url)));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => !OWNED.has(name)).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

/**
 * Serve a cached audio file, honouring a Range request.
 *
 * Returning the full body with a 200 to a ranged request is what breaks
 * seeking: the element asks for bytes 5000- and gets byte 0 onward, so it
 * either restarts or gives up. This slices the stored blob and answers a
 * proper 206 with Content-Range.
 */
async function serveRangedAudio(request, cached) {
  const range = request.headers.get("range");
  if (!range) return cached;

  const blob = await cached.blob();
  const match = /bytes=(\d+)-(\d*)/.exec(range);
  if (match === null) return cached;

  const start = Number(match[1]);
  const end = match[2] === "" ? blob.size - 1 : Number(match[2]);

  if (Number.isNaN(start) || start >= blob.size) {
    return new Response(null, {
      status: 416,
      headers: { "Content-Range": `bytes */${blob.size}` },
    });
  }

  const safeEnd = Math.min(end, blob.size - 1);
  return new Response(blob.slice(start, safeEnd + 1), {
    status: 206,
    headers: {
      "Content-Type": blob.type || "audio/mpeg",
      "Content-Length": String(safeEnd - start + 1),
      "Content-Range": `bytes ${start}-${safeEnd}/${blob.size}`,
      "Accept-Ranges": "bytes",
    },
  });
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit !== undefined) return hit;

  const response = await fetch(request);
  if (response.ok) cache.put(request, response.clone());
  return response;
}

/**
 * Pages: serve the cached copy immediately, refresh it in the background.
 * The user gets an instant load and the next visit gets the new build.
 */
async function staleWhileRevalidate(request) {
  const cache = await caches.open(PAGES);
  const hit = await cache.match(request);

  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);

  if (hit !== undefined) return hit;

  const fresh = await network;
  if (fresh !== undefined) return fresh;

  // Offline and never visited: fall back to the app shell, which boots the
  // client router and can render the route from bundled data.
  const shell = await caches.open(SHELL);
  const root = await shell.match("/");
  return root ?? Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Recitation audio lives on third-party CDNs. Serve it from the download
  // cache when present; otherwise let it go straight to the network so
  // streaming and its own range handling are untouched.
  if (request.destination === "audio" || /\.mp3(\?|$)/i.test(url.pathname)) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(AUDIO);
        const hit = await cache.match(url.href, { ignoreVary: true });
        if (hit !== undefined) return serveRangedAudio(request, hit);
        return fetch(request);
      })(),
    );
    return;
  }

  // Everything else we handle is same-origin.
  if (url.origin !== self.location.origin) return;

  // Hashed build output and bundled media never change under the same name.
  if (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/scenery/") ||
    /\.(css|js|woff2?|png|jpg|jpeg|webp|avif|svg|ico)$/i.test(url.pathname)
  ) {
    event.respondWith(cacheFirst(request, ASSETS));
    return;
  }

  if (request.mode === "navigate" || request.destination === "document") {
    event.respondWith(staleWhileRevalidate(request));
  }
});
